// Alertmanager payload 파싱.
// - 첫 번째 'firing' 알람만 처리 (resolved 는 무시)
// - 잘못된 payload 면 명시적 에러 throw → n8n 의 'Stop on error' 동작
// - dedup_key 생성 → 후속 노드에서 idempotency 보장
try {
  const body = $input.first().json.body || $input.first().json;
  const alerts = (body && body.alerts) || [];
  const firing = alerts.find(a => (a.status || 'firing') === 'firing');
  if (!firing) {
    // resolved 만 들어온 경우 정상적으로 종료 (빈 결과)
    return [];
  }
  const labels = firing.labels || {};
  const annotations = firing.annotations || {};
  if (!labels.namespace || !labels.pod) {
    throw new Error('alert missing required labels namespace/pod: ' + JSON.stringify(labels));
  }
  return [{
    json: {
      alertname:   labels.alertname || 'Unknown',
      namespace:   labels.namespace,
      pod:         labels.pod,
      container:   labels.container || 'api',
      severity:    labels.severity || 'unknown',
      summary:     annotations.summary || '',
      description: annotations.description || '',
      // dedup: 같은 알람이 5분 내 다시 와도 동일 key. 후속 워크플로우에서 K8s
      // deployment annotation 확인하여 이미 patch 됐으면 skip 하는 식으로 사용 가능.
      dedup_key:   `${labels.namespace}/${labels.pod}/${labels.container || 'api'}`,
      received_at: new Date().toISOString(),
      _raw:        body,
    }
  }];
} catch (e) {
  throw new Error('Parse Alert failed: ' + e.message);
}

// 3 HTTP 결과 + parsed alert 를 합쳐서 LLM 입력 prompt 생성.
const alertItem = $('Parse Alert').first().json;
const podItem   = $('K8s GET pod').first();
const eventItem = $('K8s GET events').first();
const logsItem  = $('K8s GET pod logs (previous)').first();

const pod      = (podItem && podItem.json) || {};
const events   = (eventItem && eventItem.json) || {};
const logsJson = (logsItem && logsItem.json) || {};

// --- describe-style 요약 (전체 dump 는 너무 길어서 핵심만) ---
const containers     = (pod.spec && pod.spec.containers) || [];
const targetName     = alertItem.container;
const container      = containers.find(c => c.name === targetName) || containers[0] || {};
const containerStat  = ((pod.status && pod.status.containerStatuses) || [])
                          .find(s => s.name === targetName)
                       || ((pod.status && pod.status.containerStatuses) || [])[0]
                       || {};
const lastState      = containerStat.lastState || {};
const limits         = (container.resources && container.resources.limits) || {};
const requests       = (container.resources && container.resources.requests) || {};

const describe = [
  `Name:      ${(pod.metadata && pod.metadata.name) || alertItem.pod}`,
  `Namespace: ${(pod.metadata && pod.metadata.namespace) || alertItem.namespace}`,
  `Status:    ${(pod.status && pod.status.phase) || 'Unknown'}`,
  `Container: ${container.name || targetName} (${container.image || 'unknown-image'})`,
  `Limits:    ${JSON.stringify(limits)}`,
  `Requests:  ${JSON.stringify(requests)}`,
  `LastState: ${JSON.stringify(lastState)}`,
  `Restarts:  ${containerStat.restartCount || 0}`,
].join('\n');

// --- logs (n8n response shape 다양: .data / .body / .text / 직접 string) ---
const logsRaw = (typeof logsJson === 'string')
  ? logsJson
  : (logsJson.data ?? logsJson.body ?? logsJson.text ?? '');
const logsText = logsRaw
  ? String(logsRaw).split('\n').slice(-80).join('\n')
  : '(no previous logs available)';

// --- events ---
const eventLines = (events.items || [])
  .slice(-15)
  .map(e => `${e.lastTimestamp || e.eventTime || ''}  ${e.type || ''}  ${e.reason || ''}  ${e.message || ''}`)
  .join('\n') || '(no events)';

// --- prompts ---
const userPrompt = `[ALERT]
${JSON.stringify({
  alertname: alertItem.alertname,
  severity:  alertItem.severity,
  summary:   alertItem.summary,
  dedup_key: alertItem.dedup_key,
})}

[POD]
namespace: ${alertItem.namespace}
name:      ${alertItem.pod}
container: ${alertItem.container}

[POD describe (truncated)]
${describe}

[Container logs — previous instance, last 80 lines]
${logsText}

[Recent events (last 15)]
${eventLines}`;

const systemPrompt = `You are a senior Kubernetes SRE and JVM/Python operations expert.
Analyze the Pod failure context and return JSON only matching this schema:
  {"root_cause": str, "confidence": int (0-100), "evidence": [str]}
- Output ONLY the JSON object. No markdown fences, no preamble.
- Cite concrete signals from the input in 'evidence'.
- Set confidence < 50 if input is insufficient.`;

// --- limit 파싱: '128Mi', '1Gi', '1024Ki', '1G', '1024' (no suffix) 모두 지원 ---
function parseMemoryToMi(s) {
  if (!s) return 128;
  const m = String(s).match(/^([0-9]+)\s*(Ki|Mi|Gi|Ti|Pi|K|M|G|T)?$/);
  if (!m) return 128;
  const n = parseInt(m[1], 10);
  switch (m[2] || 'Mi') {
    case 'Ki': return Math.max(1, Math.round(n / 1024));
    case 'Mi': return n;
    case 'Gi': return n * 1024;
    case 'Ti': return n * 1024 * 1024;
    case 'Pi': return n * 1024 * 1024 * 1024;
    case 'K':  return Math.max(1, Math.round(n * 1000 / (1024 * 1024) * 1024));
    case 'M':  return Math.round(n * 1000 / 1024);
    case 'G':  return Math.round(n * 1000 * 1000 / 1024);
    default:   return n;
  }
}

return [{
  json: {
    alert:            alertItem,
    pod_summary:      describe,
    logs_text:        logsText,
    events_text:      eventLines,
    system_prompt:    systemPrompt,
    user_prompt:      userPrompt,
    current_limit_mb: parseMemoryToMi(limits.memory),
    restart_count:    containerStat.restartCount || 0,
  }
}];

// Ollama 응답에서 message.content 파싱.
// LLM 이 JSON 외 텍스트를 섞어 보내는 경우도 자주 있어 ```fence 제거 + bracket scan 으로 fallback.
const resp = $input.first().json || {};
const raw  = (resp.message && resp.message.content) || resp.response || '{}';

function tryParse(s) {
  try { return JSON.parse(s); } catch (_) { return null; }
}

let parsed = tryParse(raw);
if (!parsed) {
  // ```json ... ``` fence 제거
  const stripped = String(raw).replace(/^```(?:json)?\s*/i, '').replace(/```\s*$/, '').trim();
  parsed = tryParse(stripped);
}
if (!parsed) {
  // 첫 번째 { 와 마지막 } 사이만 추출
  const s = String(raw);
  const a = s.indexOf('{');
  const b = s.lastIndexOf('}');
  if (a >= 0 && b > a) parsed = tryParse(s.slice(a, b + 1));
}
if (!parsed || typeof parsed !== 'object') {
  parsed = {
    root_cause: 'LLM response unparseable',
    confidence: 0,
    evidence:   [String(raw).slice(0, 200)],
    _llm_error: true,
  };
}
// confidence 정규화 (0..100 정수 유지)
parsed.confidence = Math.max(0, Math.min(100, parseInt(parsed.confidence ?? 0, 10) || 0));
parsed.evidence   = Array.isArray(parsed.evidence) ? parsed.evidence : [String(parsed.evidence || '')];

const prev = $('Build LLM Prompt').first().json;
return [{ json: { ...prev, diagnosis: parsed } }];

const prev = $('Parse LLM JSON').first().json || {};
const rl   = $input.first().json || {};
// RL stub 응답이 비정상이면 안전 기본값 사용
const remediation = {
  recommended_limit_mb:      Number(rl.recommended_limit_mb) || (prev.current_limit_mb * 2),
  recommended_hpa_threshold: Number(rl.recommended_hpa_threshold) || 70,
  recommended_hpa_max:       Number(rl.recommended_hpa_max) || 5,
  confidence:                Number(rl.confidence) || 0.5,
  reason:                    String(rl.reason || 'rl-stub fallback'),
  policy:                    String(rl.policy || 'unknown'),
};
return [{ json: { ...prev, remediation } }];

