// Slack interactivity 콜백 파싱.
// Slack 은 application/x-www-form-urlencoded ('payload=<JSON>') 또는 raw body 로 보냄.
try {
  const body = $input.first().json.body ?? $input.first().json;
  let payload;

  if (typeof body === 'string') {
    const m = body.match(/payload=([^&]+)/);
    if (!m) throw new Error('rawBody missing payload= prefix');
    payload = JSON.parse(decodeURIComponent(m[1].replace(/\+/g, ' ')));
  } else if (body && body.payload) {
    payload = typeof body.payload === 'string' ? JSON.parse(body.payload) : body.payload;
  } else if (body && body.actions) {
    payload = body;
  } else {
    throw new Error('unexpected slack payload shape: ' + Object.keys(body || {}).join(','));
  }

  const action = (payload.actions && payload.actions[0]) || {};
  let decision = {};
  if (action.value) {
    try { decision = JSON.parse(action.value); }
    catch (_) { decision = { raw: action.value }; }
  }

  return [{
    json: {
      action_id:    action.action_id || 'unknown',
      user:         (payload.user && (payload.user.name || payload.user.username)) || 'unknown',
      decision:     decision,
      response_url: payload.response_url || null,
      _slack_ts:    payload.message && payload.message.ts,
    }
  }];
} catch (e) {
  throw new Error('Parse Slack Action failed: ' + e.message);
}

